import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import SEO from "../components/seo";
import Layout from "../components/layout";
import info from "../data/data.json";

export default function SelectedProjectsRedirectPage() {
  const { t } = useTranslation();
  const { language } = useI18next();
  const portfolioHref = language === "fr" ? "/fr/portfolio/" : "/en/portfolio/";

  return (
    <Layout data={info}>
      <main className="w-full min-h-screen bg-primary p-4 text-accent sm:p-8 lg:p-12">
        <section className="mx-auto max-w-3xl rounded-2xl border border-neutral/20 bg-secondary p-8 shadow-sm">
          <p className="text-sm uppercase tracking-wide text-neutral">{t("portfolio.title")}</p>
          <h1 className="mt-3 text-3xl font-semibold tracking-tight text-accent">
            {t("selectedProjects.h1")}
          </h1>
          <p className="mt-3 text-base leading-7 text-neutral">
            {t("portfolio.homeSummary.desc")}
          </p>
          <div className="mt-6">
            <Link
              to={portfolioHref}
              className="inline-flex items-center rounded-2xl bg-accent px-5 py-3 text-sm font-semibold text-primary hover:opacity-90"
            >
              {t("portfolio.homeSummary.cta")}
            </Link>
          </div>
        </section>
      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/portfolio/" : "/en/portfolio/";
  const alternates = [
    { hrefLang: "fr", href: "https://riano.ca/fr/portfolio/" },
    { hrefLang: "en", href: "https://riano.ca/en/portfolio/" },
    { hrefLang: "x-default", href: "https://riano.ca/fr/portfolio/" },
  ];

  return (
    <>
      <meta httpEquiv="refresh" content={`0;url=${pathname}`} />
      <SEO
        data={info}
        titleKey="seo.portfolio.metaTitle"
        descriptionKey="seo.portfolio.metaDescription"
        pathname={pathname}
        currentPathname={location.pathname}
        language={language}
        alternates={alternates}
      />
    </>
  );
};
